document.querySelector('.helper-art').innerHTML=human(true);document.querySelector('.kicker').innerHTML=human();
const heading=document.querySelector('.hero h1'),bounce=document.querySelector('.ball-bounce'),kick=document.querySelector('.ball-kick'),target=document.querySelector('.target-a');
let animations=[],timer,busy=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function reset(){clearTimeout(timer);animations.forEach(a=>a.cancel());animations=[];heading.classList.remove('playing');bounce.classList.remove('ball-mode');kick.classList.remove('ball-mode');busy=false}
function play(){if(busy)return;busy=true;heading.classList.add('playing');bounce.classList.add('ball-mode');kick.classList.add('ball-mode');if(reduced.matches){timer=setTimeout(reset,3200);return}
const distance=target.getBoundingClientRect().left-kick.getBoundingClientRect().left;
animations.push(bounce.animate([{transform:'translateY(0) scale(1.12,.82)',offset:0},{transform:'translateY(-.48em) scale(.92,1.08)',offset:.44},{transform:'translateY(0) scale(1.12,.82)',offset:1}],{duration:720,iterations:Infinity,easing:'cubic-bezier(.36,0,.66,1)'}));
animations.push(kick.animate([{transform:'translate(0,0) rotate(0)',offset:0},{transform:'translate(0,0) rotate(-15deg)',offset:.18},{transform:`translate(${distance*.52}px,-.17em) rotate(220deg)`,offset:.4},{transform:`translate(${distance}px,0) rotate(430deg)`,offset:.57},{transform:`translate(${distance}px,0) rotate(430deg)`,offset:.7},{transform:'translate(0,0) rotate(0)',offset:1}],{duration:2900,delay:150,easing:'ease-in-out',fill:'both'}));
animations.push(target.animate([{transform:'rotate(0)'},{transform:'translateX(.06em) rotate(13deg)'},{transform:'rotate(-5deg)'},{transform:'rotate(0)'}],{duration:550,delay:1750,easing:'ease-out'}));timer=setTimeout(()=>{reset();if(heading.matches(":hover, :focus-visible"))play()},3400)}
heading.addEventListener('pointerenter',play);heading.addEventListener('focus',play);heading.addEventListener('click',play);heading.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();play()}});heading.addEventListener('pointerleave',()=>{if(!busy)reset()});
const help=document.querySelector('.help-trigger'),panel=document.querySelector('#help-panel'),dock=document.querySelector('.help-dock');let previousFocus;
function helpOpen(open){panel.hidden=!open;help.setAttribute('aria-expanded',String(open));dock.classList.toggle('open',open);if(open){previousFocus=document.activeElement;panel.querySelector('button').focus()}else if(previousFocus)help.focus()}
help.onclick=()=>helpOpen(panel.hidden);document.querySelector('.help-close').onclick=()=>helpOpen(false);panel.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>helpOpen(false)));document.addEventListener('keydown',e=>{if(e.key==='Escape')helpOpen(false)});document.addEventListener('pointerdown',e=>{if(!panel.hidden&&!panel.contains(e.target)&&!dock.contains(e.target))helpOpen(false)});
document.querySelector('.theme-toggle').onclick=()=>{const dark=document.documentElement.dataset.theme!=='dark';document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('start-whimsy-theme',dark?'dark':'light')};try{document.documentElement.dataset.theme=localStorage.getItem('start-whimsy-theme')||'light'}catch{}
document.querySelector('.nav-menu-btn').onclick=function(){const open=document.querySelector('.nav').classList.toggle('open');this.setAttribute('aria-expanded',String(open))};
let saved;try{saved=new Set(JSON.parse(localStorage.getItem('start-whimsy-favorites')||'[]'))}catch{saved=new Set()}
function syncHeart(b){const on=saved.has(b.getAttribute('aria-label'));b.setAttribute('aria-pressed',String(on));b.textContent=on?'♥':'♡'}document.querySelectorAll('.heart').forEach(syncHeart);
document.addEventListener('click',e=>{const b=e.target.closest('.heart');if(!b)return;const key=b.getAttribute('aria-label');saved.has(key)?saved.delete(key):saved.add(key);syncHeart(b);localStorage.setItem('start-whimsy-favorites',JSON.stringify([...saved]))});
document.querySelector('#all-games').onclick=function(){const expanded=document.querySelector('#expanded-games');if(!expanded.innerHTML){expanded.innerHTML=window.extraCards;expanded.querySelectorAll('.heart').forEach(syncHeart)}expanded.hidden=!expanded.hidden;this.textContent=expanded.hidden?'See all 188 games →':'Show fewer games ↑';this.setAttribute('aria-expanded',String(!expanded.hidden))};
document.querySelector('.scroll-jump').onclick=()=>window.scrollTo({top:scrollY<300?document.documentElement.scrollHeight:0,behavior:reduced.matches?'instant':'smooth'});const jump=()=>{const b=document.querySelector('.scroll-jump');b.textContent=scrollY<300?'↓':'↑';b.setAttribute('aria-label',scrollY<300?'Scroll to bottom':'Back to top')};addEventListener('scroll',jump,{passive:true});jump();

